// 1. Ambil teks isi email mentah dari node sebelumnya
const emailBody = $input.item.json.text || "";

// 2. Rumus Regex khusus DANA untuk mencari pola uang (misal: Rp 50.247)
const regexDana = /(?:Rp|IDR)\s*([\d\.]+)/i;
const match = emailBody.match(regexDana);

let nominalBersih = 0;
if (match && match[1]) {
    // Hilangkan tanda titik ribuan agar terbaca sebagai angka bulat (50247)
    nominalBersih = parseInt(match[1].replace(/\./g, ''));
}

// 3. Kirim data yang sudah bersih ke node berikutnya
return {
  json: {
    nominal_mutasi: nominalBersih,
    subjek: $input.item.json.subject,
    waktu: $input.item.json.date
  }
};

const emailBody = $input.item.json.text || "";

// REGEX khusus mendeteksi nominal setelah kata kunci uang/transfer masuk di SeaBank
const regexSeaBank = /(?:Rp|IDR)\s*([\d\.]+)/i;
const match = emailBody.match(regexSeaBank);

let nominalBersih = 0;
if (match && match[1]) {
    nominalBersih = parseInt(match[1].replace(/\./g, ''));
}

return {
  json: {
    nominal_mutasi: nominalBersih, // Variabel harus sama persis dengan jalur DANA
    subjek: $input.item.json.subject,
    waktu: $input.item.json.date
  }
};
